/**
 * Generates the tender_authorities seed migration from the ONS Open Geography portal.
 *
 * Not part of `npm run migrate` — run manually when the council list needs refreshing
 * (e.g. after local government reorganisation), then commit the regenerated file:
 *
 *   node scripts/generate-authority-seed.js > sql/migrations/117_seed_tender_authorities.sql
 *
 * Sources (ONS ArcGIS, update service names to the latest vintage when re-running):
 *  - Local Authority Districts names & codes (UK)
 *  - County Councils names & codes (England)
 *  - Combined Authorities names & codes (England)
 *  - Ward lookup for LAD -> Region mapping (England; Wales/Scotland derived from code prefix)
 */

const ONS_BASE = 'https://services1.arcgis.com/ESMARspQHYMw9BZ9/arcgis/rest/services';

const LAD_SERVICE = `${ONS_BASE}/LAD_APR_2025_UK_NC_v2/FeatureServer/0/query`;
const CTY_SERVICE = `${ONS_BASE}/CTY_DEC_2025_EN_NC/FeatureServer/0/query`;
const CAUTH_SERVICE = `${ONS_BASE}/CAUTH_MAY_2025_EN_NC/FeatureServer/0/query`;
const REGION_LOOKUP_SERVICE = `${ONS_BASE}/WD25_LAD25_CTYUA25_RGN25_CTRY25_UK_LU/FeatureServer/0/query`;

// GSS code prefix -> authority_type. N09 (Northern Ireland) deliberately excluded.
const TYPE_BY_PREFIX = {
  E06: 'unitary',
  E07: 'district',
  E08: 'metropolitan',
  E09: 'london_borough',
  W06: 'unitary',
  S12: 'unitary',
  E10: 'county',
  E47: 'combined',
};

async function fetchAllFeatures(serviceUrl, outFields, distinct = false) {
  const features = [];
  let offset = 0;
  for (;;) {
    const params = new URLSearchParams({
      where: '1=1',
      outFields,
      f: 'json',
      resultOffset: String(offset),
      returnGeometry: 'false',
    });
    if (distinct) params.set('returnDistinctValues', 'true');
    const response = await fetch(`${serviceUrl}?${params}`, {
      headers: { Accept: 'application/json' },
      signal: AbortSignal.timeout(30_000),
    });
    if (!response.ok) {
      throw new Error(`ONS request failed (${response.status}): ${serviceUrl}`);
    }
    const data = await response.json();
    if (data.error) throw new Error(`ONS error: ${JSON.stringify(data.error)}`);
    const batch = data.features || [];
    features.push(...batch);
    if (!data.exceededTransferLimit || batch.length === 0) break;
    offset += batch.length;
  }
  return features.map((f) => f.attributes);
}

function sqlEscape(value) {
  return value.replace(/'/g, "''");
}

async function main() {
  const [lads, counties, cauths, regionRows] = await Promise.all([
    fetchAllFeatures(LAD_SERVICE, 'LAD25CD,LAD25NM'),
    fetchAllFeatures(CTY_SERVICE, 'CTY25CD,CTY25NM'),
    fetchAllFeatures(CAUTH_SERVICE, 'CAUTH25CD,CAUTH25NM'),
    fetchAllFeatures(REGION_LOOKUP_SERVICE, 'LAD25CD,RGN25NM', true),
  ]);

  const regionByLad = new Map();
  for (const row of regionRows) {
    if (row.LAD25CD && row.RGN25NM) regionByLad.set(row.LAD25CD, row.RGN25NM);
  }

  const rows = [];
  const addRow = (code, name) => {
    if (!code || !name) return;
    const type = TYPE_BY_PREFIX[code.slice(0, 3)];
    if (!type) return; // skips N09 and anything unexpected
    let region = regionByLad.get(code) || null;
    if (!region && code.startsWith('W')) region = 'Wales';
    if (!region && code.startsWith('S')) region = 'Scotland';
    rows.push({ code, name, region, type });
  };

  for (const lad of lads) addRow(lad.LAD25CD, lad.LAD25NM);
  for (const cty of counties) addRow(cty.CTY25CD, cty.CTY25NM);
  // Suffix combined authorities so names stay unique (e.g. Lancashire CC vs Lancashire CA)
  for (const ca of cauths) {
    if (ca.CAUTH25NM) addRow(ca.CAUTH25CD, `${ca.CAUTH25NM} Combined Authority`);
  }
  rows.push({ code: 'E61000001', name: 'Greater London Authority', region: 'London', type: 'combined' });

  rows.sort((a, b) => a.code.localeCompare(b.code));

  const values = rows
    .map((r) => {
      const region = r.region ? `'${sqlEscape(r.region)}'` : 'NULL';
      return `  ('${sqlEscape(r.name)}', '${r.code}', ${region}, '${r.type}')`;
    })
    .join(',\n');

  process.stdout.write(
    `-- Generated by scripts/generate-authority-seed.js on ${new Date().toISOString().slice(0, 10)}\n` +
      `-- ${rows.length} authorities: GB councils + English county councils + combined authorities + GLA\n\n` +
      `INSERT INTO scraper.tender_authorities (name, canonical_code, region, authority_type) VALUES\n` +
      `${values}\n` +
      `ON CONFLICT (canonical_code) DO NOTHING;\n`
  );
}

main().catch((err) => {
  console.error('[generate-authority-seed] failed:', err.message);
  process.exit(1);
});
